// Package workflowtest runs a workflow generated by `hatch ci` the way a CI
// runner would — YAML parsing, then the provider's shell — against a fake
// Hatch binary, and returns the exact argv the CLI received. Test-only helper.
package workflowtest

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

// FakeHatch is the "binary" the stub downloader serves: a shell script that
// records each argument NUL-terminated in $HATCH_FAKE_ARGV.
const FakeHatch = "#!/bin/sh\n: > \"$HATCH_FAKE_ARGV\"\nfor a in \"$@\"; do printf '%s\\000' \"$a\" >> \"$HATCH_FAKE_ARGV\"; done\n"

// FakeHatchSHA256 is the hex sha256 of FakeHatch.
func FakeHatchSHA256() string {
	sum := sha256.Sum256([]byte(FakeHatch))
	return hex.EncodeToString(sum[:])
}

// Deploy is the deploy step extracted from a generated workflow.
type Deploy struct {
	Env    map[string]string // job environment (GitHub step env / GitLab variables)
	Script string            // the install+deploy shell script
	Shell  string            // GitHub step shell ("" for GitLab)
	// NoExpand lists GitLab variables declared with expand: false.
	NoExpand map[string]bool
}

// Extract parses a generated workflow and returns its deploy step.
func Extract(provider, content string) (Deploy, error) {
	switch provider {
	case "github":
		var wf struct {
			Jobs map[string]struct {
				Steps []struct {
					Name  string            `yaml:"name"`
					Shell string            `yaml:"shell"`
					Env   map[string]string `yaml:"env"`
					Run   string            `yaml:"run"`
				} `yaml:"steps"`
			} `yaml:"jobs"`
		}
		if err := yaml.Unmarshal([]byte(content), &wf); err != nil {
			return Deploy{}, fmt.Errorf("github workflow is not valid YAML: %w", err)
		}
		steps := wf.Jobs["deploy"].Steps
		if len(steps) == 0 {
			return Deploy{}, fmt.Errorf("github workflow has no deploy steps")
		}
		last := steps[len(steps)-1]
		return Deploy{Env: last.Env, Script: last.Run, Shell: last.Shell}, nil
	case "gitlab":
		var wf struct {
			Deploy struct {
				Variables map[string]struct {
					Value  string `yaml:"value"`
					Expand *bool  `yaml:"expand"`
				} `yaml:"variables"`
				Script []string `yaml:"script"`
			} `yaml:"deploy"`
		}
		if err := yaml.Unmarshal([]byte(content), &wf); err != nil {
			return Deploy{}, fmt.Errorf("gitlab workflow is not valid YAML: %w", err)
		}
		if len(wf.Deploy.Script) == 0 {
			return Deploy{}, fmt.Errorf("gitlab job has no script")
		}
		d := Deploy{Env: map[string]string{}, NoExpand: map[string]bool{}, Script: wf.Deploy.Script[len(wf.Deploy.Script)-1]}
		for k, v := range wf.Deploy.Variables {
			d.Env[k] = v.Value
			if v.Expand != nil && !*v.Expand {
				d.NoExpand[k] = true
			}
		}
		return d, nil
	}
	return Deploy{}, fmt.Errorf("unknown provider %q", provider)
}

// Result is the outcome of running a deploy script.
type Result struct {
	Argv   []string // argv received by the fake hatch (nil if it never ran)
	URL    string   // URL the stub downloader was asked for
	Output string   // combined stdout+stderr of the script
	Err    error    // script exit error
}

// Run executes the deploy script with /bin/sh in workdir, a minimal
// environment (the step env + PATH + extra), and a stub `curl` serving served
// as the downloaded binary.
func Run(d Deploy, workdir string, served string, extra map[string]string) (Result, error) {
	stubDir, err := os.MkdirTemp("", "hatch-wf-stub")
	if err != nil {
		return Result{}, err
	}
	defer os.RemoveAll(stubDir)
	payload := filepath.Join(stubDir, "payload")
	urlFile := filepath.Join(stubDir, "url")
	argvFile := filepath.Join(stubDir, "argv")
	if err := os.WriteFile(payload, []byte(served), 0o644); err != nil {
		return Result{}, err
	}
	curl := "#!/bin/sh\nout=\nwhile [ $# -gt 0 ]; do case \"$1\" in -o) out=\"$2\"; shift 2;; -*) shift;; *) printf '%s' \"$1\" > " +
		shQuote(urlFile) + "; shift;; esac; done\ncp " + shQuote(payload) + " \"$out\"\n"
	if err := os.WriteFile(filepath.Join(stubDir, "curl"), []byte(curl), 0o755); err != nil {
		return Result{}, err
	}

	env := []string{"PATH=" + stubDir + ":/usr/bin:/bin", "HOME=" + workdir, "HATCH_FAKE_ARGV=" + argvFile}
	for k, v := range d.Env {
		env = append(env, k+"="+v)
	}
	for k, v := range extra {
		env = append(env, k+"="+v)
	}
	args := []string{"-c", d.Script}
	if d.Shell == "sh" { // GitHub `shell: sh` runs `sh -e {0}`
		args = []string{"-e", "-c", d.Script}
	}
	cmd := exec.Command("/bin/sh", args...)
	cmd.Dir = workdir
	cmd.Env = env
	var out bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &out
	res := Result{Err: cmd.Run(), Output: out.String()}
	if b, err := os.ReadFile(urlFile); err == nil {
		res.URL = string(b)
	}
	if b, err := os.ReadFile(argvFile); err == nil {
		res.Argv = strings.Split(strings.TrimSuffix(string(b), "\x00"), "\x00")
		if len(b) == 0 {
			res.Argv = []string{}
		}
	}
	return res, nil
}

// FakePip is the `pip` the build-step runner puts on PATH. It records each
// install request in $HATCH_FAKE_PIP_LOG and fails the way real pip does when
// the file or project it is asked to install from is missing.
const FakePip = `#!/bin/sh
[ "$1" = install ] || { echo "fake pip: unexpected command: $*" >&2; exit 2; }
shift
printf '%s\n' "$*" >> "$HATCH_FAKE_PIP_LOG"
case "$1" in
  -r) [ -f "$2" ] || { echo "ERROR: Could not open requirements file: [Errno 2] No such file or directory: '$2'" >&2; exit 1; } ;;
  .) [ -f pyproject.toml ] || [ -f setup.py ] || { echo "ERROR: Directory '.' is not installable. Neither 'setup.py' nor 'pyproject.toml' found." >&2; exit 1; } ;;
  *) echo "fake pip: unexpected install target: $*" >&2; exit 2 ;;
esac
`

// BuildCommands returns the shell commands of a generated workflow that run
// before the deploy step: GitHub `run:` steps and GitLab script lines, in order.
func BuildCommands(provider, content string) ([]string, error) {
	switch provider {
	case "github":
		var wf struct {
			Jobs map[string]struct {
				Steps []struct {
					Run string `yaml:"run"`
				} `yaml:"steps"`
			} `yaml:"jobs"`
		}
		if err := yaml.Unmarshal([]byte(content), &wf); err != nil {
			return nil, fmt.Errorf("github workflow is not valid YAML: %w", err)
		}
		steps := wf.Jobs["deploy"].Steps
		if len(steps) == 0 {
			return nil, fmt.Errorf("github workflow has no deploy steps")
		}
		var cmds []string
		for _, st := range steps[:len(steps)-1] { // the last step is the deploy
			if st.Run != "" {
				cmds = append(cmds, st.Run)
			}
		}
		return cmds, nil
	case "gitlab":
		var wf struct {
			Deploy struct {
				Script []string `yaml:"script"`
			} `yaml:"deploy"`
		}
		if err := yaml.Unmarshal([]byte(content), &wf); err != nil {
			return nil, fmt.Errorf("gitlab workflow is not valid YAML: %w", err)
		}
		if len(wf.Deploy.Script) == 0 {
			return nil, fmt.Errorf("gitlab job has no script")
		}
		return wf.Deploy.Script[:len(wf.Deploy.Script)-1], nil // the last line is the deploy
	}
	return nil, fmt.Errorf("unknown provider %q", provider)
}

// RunBuild runs build commands one by one with /bin/sh -e in workdir (the
// checked-out project), with FakePip as `pip`, stopping at the first failure.
// It returns the pip install requests seen (one "args" string each), the
// combined output, and the first command error, if any.
func RunBuild(cmds []string, workdir string) (installs []string, output string, err error) {
	stubDir, mkErr := os.MkdirTemp("", "hatch-wf-pip")
	if mkErr != nil {
		return nil, "", mkErr
	}
	defer os.RemoveAll(stubDir)
	logFile := filepath.Join(stubDir, "pip.log")
	if wErr := os.WriteFile(filepath.Join(stubDir, "pip"), []byte(FakePip), 0o755); wErr != nil {
		return nil, "", wErr
	}
	var out bytes.Buffer
	for _, c := range cmds {
		cmd := exec.Command("/bin/sh", "-e", "-c", c)
		cmd.Dir = workdir
		cmd.Env = []string{"PATH=" + stubDir + ":/usr/bin:/bin", "HOME=" + workdir, "HATCH_FAKE_PIP_LOG=" + logFile}
		cmd.Stdout, cmd.Stderr = &out, &out
		if runErr := cmd.Run(); runErr != nil {
			err = fmt.Errorf("build command %q failed: %w", c, runErr)
			break
		}
	}
	if b, rErr := os.ReadFile(logFile); rErr == nil {
		installs = strings.Split(strings.TrimSuffix(string(b), "\n"), "\n")
	}
	return installs, out.String(), err
}

func shQuote(s string) string { return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'" }
